"""Near-bound whole-batch stress: 8 runs, 100k expanded ops, 60k enqueues."""
import json, random, subprocess, sys, time
rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 99)
U = 1 << 24
def part(k):
    if k <= 1:
        return [0, U]
    return [0] + sorted(rng.sample(range(1, U), k - 1)) + [U]
plans = [
    ('sff', 16, 8, 64), ('wfq', 8, 4, 32), ('fifo', 4, 2, 16), ('sp', 2, 8, 40),
    ('sff', 8, 2, 8), ('wfq', 4, 4, 24), ('fifo', 16, 1, 48), ('sp', 1, 8, 12),
]
runs = []
total_enq = 60000
for idx, (kind, M, L, R) in enumerate(plans):
    flows = list(range(6))
    if kind == 'sp':
        policy = {'kind': 'sp', 'levels': [[f, rng.randrange(U)] for f in flows]}
    elif kind == 'wfq':
        policy = {'kind': 'wfq', 'weights': [[f, rng.randint(1, 1024)] for f in flows]}
    else:
        policy = {'kind': kind}
    ev, nid, ops = [], idx * 200000 + 1, 0
    saved = []
    while ops < 12500 and total_enq > 0:
        pick = rng.random()
        if pick < 0.55:
            ev.append(['enqueue', nid, rng.choice(flows), rng.randint(1, 9000), rng.randrange(U)])
            nid += 1; ops += 1; total_enq -= 1
        elif pick < 0.80:
            n = rng.randint(1, 4); ev.append(['dequeue', n]); ops += n
        elif pick < 0.85:
            ev.append(['sample']); ops += 1
        elif pick < 0.90:
            ev.append(['cancel', rng.randrange(1, nid)]); ops += 1
        elif pick < 0.94:
            ev.append(['inspect', rng.randrange(1, nid)]); ops += 1
        elif pick < 0.97 or not saved:
            name = rng.randrange(4)
            ev.append(['save', name]); saved.append(name); ops += 1
        else:
            ev.append(['restore', rng.choice(saved)]); ops += 1
    if idx % 3 == 0:      # ping-pong branch exploration at the end
        for _ in range(300):
            ev.append(['restore', saved[_ % len(saved)]])
            for _ in range(4):
                ev.append(['enqueue', nid, 0, 120, rng.randrange(U)]); nid += 1
    runs.append({'banks': M, 'load_balancers': L,
                 'fifo_bytes': rng.choice([12000, 10 ** 7, 10 ** 9]),
                 'pifo_bytes': rng.choice([9000, 10 ** 6, 10 ** 9]),
                 'refill_batch': rng.choice([1, 8, 32]),
                 'sample_period': rng.choice([10, 100, 5000]),
                 'borders': part(R), 'policy': policy, 'events': ev})
data = json.dumps({'runs': runs}).encode()
print('input bytes', len(data), 'events', sum(len(r['events']) for r in runs),
      'enqueues', sum(1 for r in runs for e in r['events'] if e[0] == 'enqueue'))
open('/workspace/tmp/mega.json', 'wb').write(data)
start = time.time()
proc = subprocess.run([sys.executable, '-I', '-B', '/workspace/submission/cli.py'],
                      input=data, capture_output=True)
print('rc', proc.returncode, 'wall %.2f' % (time.time() - start), 'out', len(proc.stdout))
if proc.returncode or proc.stdout.startswith(b'{"error"'):
    print(proc.stderr.decode()[-3000:])
